// UB: Signed Integer Overflow
// Compiler assumes this operation will not wrap,
// enabling aggressive optimization assumptions.
int max_val = 2147483647;
int result = max_val + 1;


// UB: Sequence Point Violation
// Order of evaluation is unspecified.
int i = 5;
int arr[10];
int k = arr[i++] + arr[i++]; 

// Also UB:
int j = i + (++i);


// IDB: Right Shift on Negative Signed Integer
// Result depends on whether the implementation uses
// arithmetic (sign-extending) or logical shift.
int x = -10;
int y = x >> 2;


// UB: Strict Aliasing Violation (Type Punning)
// Accessing memory written via one type (float)
// using a pointer to an incompatible type (int*).
float f = 10.0f;
int* i_ptr = (int*)&f; // C-style cast does not prevent UB
int value = *i_ptr;    // UB triggered upon dereference

// Note: char* and void* are exceptions to aliasing rules.
